function inventory(p,excludeOrder){
 let consumed=0,reserved=p.reserved;
 data.orders.filter(o=>!o.seed&&o.id!==excludeOrder).forEach(o=>o.items.filter(i=>i.id===p.id).forEach(i=>{if(o.payment==='paid')consumed+=i.qty;else reserved+=i.qty;}));
 return {stock:round(p.stock-consumed),reserved:round(reserved),free:round(p.stock-consumed-reserved)};
}
